cat > /tmp/analyze.py << 'END'
import gzip, csv
from collections import Counter, defaultdict
from pathlib import Path

path = Path("/workspace/data/erate_frn_status_fy2024.csv.gz")
with gzip.open(path, "rt", encoding="utf-8", errors="replace", newline="") as fh:
    rows = [{k: (v or "").strip() for k, v in row.items()} for row in csv.DictReader(fh)]

by_frn = defaultdict(dict)
for r in rows:
    by_frn[r["funding_request_number"]][r["form_version"]] = r

def fnum(x):
    try:
        return float(x) if x != "" else None
    except Exception:
        return None

print("=== current status x wave x commit ===")
print(Counter((r["form_471_frn_status_name"], bool(r["wave_sequence_number"]),
               "0" if fnum(r["funding_commitment_request"])==0 else ("blank" if fnum(r["funding_commitment_request"]) is None else ">0"))
              for r in rows if r["form_version"]=="Current"))

print("\n=== current status x appeal x commit0 ===")
print(Counter((r["form_471_frn_status_name"], bool(r["appeal_wave_number"]),
               "0" if fnum(r["funding_commitment_request"])==0 else (">0" if (fnum(r["funding_commitment_request"]) or 0)>0 else "blank"))
              for r in rows if r["form_version"]=="Current"))

has_orig = {frn for frn,d in by_frn.items() if "Original" in d}
print("\ncurrent-only wave by status", Counter((r["form_471_frn_status_name"], bool(r["wave_sequence_number"])) for r in rows if r["form_version"]=="Current" and r["funding_request_number"] not in has_orig))

print("\ncurrent wave empty AND has original count by status")
print(Counter(d["Current"]["form_471_frn_status_name"] for d in by_frn.values() if "Current" in d and "Original" in d and not d["Current"]["wave_sequence_number"]))

print("\n=== field diffs by current status (counts) ===")
fields = ["funding_commitment_request","total_pre_discount_costs","dis_pct","months_of_service","appeal_wave_number","wave_sequence_number","contract_type_name","bid_count","organization_name"]
for st in ["QK7","ZP2","VR9","VD4"]:
    diffs = Counter()
    n = 0
    commit_dir = Counter()
    for d in by_frn.values():
        if "Current" not in d or "Original" not in d: continue
        if d["Current"]["form_471_frn_status_name"]!=st: continue
        n += 1
        o, c = d["Original"], d["Current"]
        for f in fields:
            if o[f] != c[f]:
                diffs[f] += 1
        fo, fc = fnum(o["funding_commitment_request"]), fnum(c["funding_commitment_request"])
        if fo is None or fc is None:
            commit_dir["blank"] += 1
        elif abs(fo-fc)<1e-6:
            commit_dir["eq"] += 1
        elif fc < fo:
            commit_dir["reduced"] += 1
        else:
            commit_dir["increased"] += 1
        if fc == 0 and fo and fo > 0:
            commit_dir["zeroed_from_positive"] += 1
    print(st, "n_both", n, "commit_dir", dict(commit_dir))
    print("  diffs", dict(diffs))

print("\ncurrent commitment blank")
for r in rows:
    if r["form_version"]=="Current" and not r["funding_commitment_request"]:
        print(r["funding_request_number"], r["form_471_frn_status_name"], "wave", r["wave_sequence_number"], "pre", r["total_pre_discount_costs"], "months", r["months_of_service"], "dis", r["dis_pct"], "pending", r["pending_reason"])

# discount vs commitment consistency: committed ~= pre * dis?
print("\n=== commitment vs pre*dis agreement by status (current) ===")
for st in ["QK7","ZP2","VR9","VD4"]:
    agree = disagree = blank = zero = 0
    for r in rows:
        if r["form_version"]!="Current" or r["form_471_frn_status_name"]!=st: continue
        c, p, d = fnum(r["funding_commitment_request"]), fnum(r["total_pre_discount_costs"]), fnum(r["dis_pct"])
        if c is None or p is None or d is None:
            blank += 1
            continue
        if c == 0:
            zero += 1
        expected = round(p * d, 2)
        if abs(c - expected) < 0.02:
            agree += 1
        else:
            disagree += 1
    print(st, "agree", agree, "disagree", disagree, "blank", blank, "zero", zero)

print("\n=== same check ORIGINAL by later current status ===")
for st in ["QK7","ZP2","VR9","VD4"]:
    agree = disagree = blank = 0
    for d in by_frn.values():
        if "Current" not in d or "Original" not in d: continue
        if d["Current"]["form_471_frn_status_name"]!=st: continue
        r = d["Original"]
        c, p, disc = fnum(r["funding_commitment_request"]), fnum(r["total_pre_discount_costs"]), fnum(r["dis_pct"])
        if c is None or p is None or disc is None:
            blank += 1
            continue
        expected = round(p * disc, 2)
        if abs(c - expected) < 0.02:
            agree += 1
        else:
            disagree += 1
    print(st, "orig agree", agree, "disagree", disagree, "blank", blank)

print("DONE")
END
